  throw new Error(`Worker payload missing company_name for Id ${body.Id}`);
}
const candidateHomepage = normalizeHomepage(body.candidate_homepage || body.website_url || body.best_url || '');
const candidateDomain = extractDomain(body.candidate_domain || candidateHomepage || body.best_url || body.url_validated || '');
const searchLoose = stripLegalSuffix(companyName) || companyName;
function toBooleanFlag(value) {
  if (typeof value === 'boolean') return value;
  const raw = String(value || '').trim().toLowerCase();
  if (!raw) return false;
  if (['false','0','no','off','null','undefined'].includes(raw)) return false;
  if (['true','1','yes','on'].includes(raw)) return true;
  return Boolean(value);
}
const checkpointUrlOnly = toBooleanFlag(body.checkpoint_url_only ?? body.test_url_checkpoint ?? false);
