function cleanText(value) {
  const raw = String(value ?? '').trim();
  if (!raw) return '';
  const lowered = raw.toLowerCase();
  if (['undefined','null','n/a','na','none'].includes(lowered)) return '';
  return raw;
}
function stripFences(value) {
