  if (relation && relation[1]) text = relation[1];
  text = text.split(/(?:\s+(?:that|which|who|offering|providing|with|to|for|across|in|at|on)\b|[.;,])/i)[0] || text;
  text = cleanBusinessName(text).replace(/^the\s+/i, '').trim();
  return text.replace(/^[^A-Za-z0-9]+/, '').replace(/\s+/g, ' ').trim();
