    /\b(?:part\s+of|member\s+of|under|owned\s+by|subsidiary\s+of)\s+(?:the\s+)?([A-Z][A-Za-z0-9&+.,'()\- ]{2,90}?)(?=(?:\s+(?:offering|providing|with|that|which|who|to|for|across|in|at|on)\b)|[.;,\n]|$)/gi,
